import json

# Verify the report structure
with open('outputs/t05_gtfs_cleaning_report.json', 'r') as f:
    report = json.load(f)

required_fields = ['invalid_coordinates_removed', 'duplicate_stops_removed', 'missing_stop_names_filled', 'n_clean_stops', 'n_clean_stop_times']

for field in required_fields:
    if field not in report:
        print(f'MISSING: {field}')
    elif not isinstance(report[field], int):
        print(f'WRONG TYPE: {field} is {type(report[field]).__name__}, expected int')
    else:
        print(f'OK: {field} = {report[field]}')
